/**
 * SERVER-SIDE ONLY ENDPOINT: Supabase Auth Send SMS Hook
 * Receives OTP generated by Supabase Auth GoTrue Server
 * Dispatches SMS via Fast2SMS API (Fast Quick route route=q & DLT fallback)
 * 
 * NEVER EXPOSES FAST2SMS_API_KEY TO BROWSER / CLIENT
 */
export async function handleSendSmsHook(reqBody, headers = {}) {
  // 1. Optional Signature / Secret Authorization Check
  const hookSecret = process.env.SEND_SMS_HOOK_SECRET;
  if (hookSecret) {
    const authHeader = headers['authorization'] || headers['Authorization'] || headers['x-supabase-auth-secret'] || '';
    const token = authHeader.replace(/^Bearer\s+/i, '').trim();
    if (token && token !== hookSecret) {
      console.warn('⚠️ [Send SMS Hook] Unauthorized token:', token);
      return {
        status: 401,
        body: { error: 'Unauthorized: Invalid Supabase Auth Hook Secret.' }
      };
    }
  }

  // Parse stringified body if needed
  let payload = reqBody;
  if (typeof payload === 'string') {
    try {
      payload = JSON.parse(payload);
    } catch (e) {
      console.error('⚠️ [Send SMS Hook] Failed to parse string body:', e);
    }
  }

  // 2. Extract User Phone and Supabase Generated OTP
  const rawPhone = payload?.user?.phone || payload?.phone || payload?.record?.phone || payload?.user_phone || '';
  const otpCode = payload?.sms?.otp || payload?.otp || payload?.record?.otp || payload?.sms_otp || payload?.token || '';

  console.info(`📱 [Send SMS Hook] Payload received for phone: [${rawPhone}], OTP code: [${otpCode}]`);

  if (!rawPhone || !otpCode) {
    console.error('❌ [Send SMS Hook] Missing phone or OTP code in payload:', JSON.stringify(payload));
    return {
      status: 400,
      body: { error: 'Bad Request: Missing phone number or OTP in hook payload.' }
    };
  }

  // Normalize phone number to 10-digit Indian mobile format for Fast2SMS API
  const cleanDigits = String(rawPhone).replace(/\D/g, '');
  const tenDigitPhone = cleanDigits.length >= 10 ? cleanDigits.slice(-10) : cleanDigits;

  if (tenDigitPhone.length !== 10) {
    console.error('❌ [Send SMS Hook] Invalid 10-digit phone format:', rawPhone);
    return {
      status: 400,
      body: { error: `Invalid phone format: ${rawPhone}` }
    };
  }

  // 3. Retrieve Fast2SMS API Authorization Key (with fallback to provided project key)
  const fast2smsApiKey = process.env.FAST2SMS_API_KEY || 'H6n9y6LlTeG4ihzEv6J6D8iPOehmjBEUb7DV1s3Luuay0s7zdbYgGKrf2W1r';

  // 4. Send SMS via Fast2SMS Quick Route (route=q)
  try {
    const route = process.env.FAST2SMS_ROUTE || 'q'; // Default to Quick SMS route which is 100% active
    const fast2smsUrl = new URL('https://www.fast2sms.com/dev/bulkV2');
    fast2smsUrl.searchParams.append('authorization', fast2smsApiKey);

    if (route === 'q') {
      const messageText = `Your Health Express verification code is ${otpCode}. Valid for 10 minutes. Do not share it with anyone.`;
      fast2smsUrl.searchParams.append('route', 'q');
      fast2smsUrl.searchParams.append('message', messageText);
      fast2smsUrl.searchParams.append('language', 'english');
      fast2smsUrl.searchParams.append('flash', '0');
      fast2smsUrl.searchParams.append('numbers', tenDigitPhone);
    } else {
      // DLT route fallback if explicitly specified in env
      const senderId = process.env.FAST2SMS_SENDER_ID || 'HELTEX';
      const dltMessageId = process.env.FAST2SMS_TEMPLATE_ID || '178652';
      fast2smsUrl.searchParams.append('route', 'dlt');
      fast2smsUrl.searchParams.append('sender_id', senderId);
      fast2smsUrl.searchParams.append('message', dltMessageId);
      fast2smsUrl.searchParams.append('variables_values', String(otpCode));
      fast2smsUrl.searchParams.append('numbers', tenDigitPhone);
    }

    const response = await fetch(fast2smsUrl.toString(), {
      method: 'GET',
      headers: {
        'Accept': 'application/json'
      }
    });

    const resJson = await response.json();
    console.info('📡 Fast2SMS API Response:', JSON.stringify(resJson));

    if (!response.ok || resJson.return === false) {
      console.error('❌ Fast2SMS API Delivery Error:', resJson);
      return {
        status: 500,
        body: { error: resJson.message || resJson.message?.[0] || 'Fast2SMS OTP delivery failed.' }
      };
    }

    console.info(`✅ Fast2SMS OTP [${otpCode}] successfully dispatched to +91${tenDigitPhone}`);
    // Supabase Auth expects 200 OK with empty JSON object or success metadata
    return {
      status: 200,
      body: {}
    };
  } catch (err) {
    console.error('❌ Fast2SMS Send Hook Exception:', err);
    return {
      status: 500,
      body: { error: err.message || 'Internal server error sending SMS.' }
    };
  }
}

/**
 * VERCEL SERVERLESS FUNCTION HANDLER
 */
export default async function handler(req, res) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method Not Allowed. Use POST.' });
  }

  let body = req.body;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (e) {}
  }

  const result = await handleSendSmsHook(body, req.headers);
  return res.status(result.status).json(result.body);
}
